import{_ as r,o as t,c as i,ah as n}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Cast-Profil: August Wöginger – Das Wunder der Funktionärs-Evolution","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/profil-august-woeginger.md","filePath":"recherche/profil-august-woeginger.md"}'),a={name:"recherche/profil-august-woeginger.md"};function o(s,e,u,l,d,g){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="cast-profil-august-woginger-–-das-wunder-der-funktionars-evolution" tabindex="-1">Cast-Profil: August Wöginger – Das Wunder der Funktionärs-Evolution <a class="header-anchor" href="#cast-profil-august-woginger-–-das-wunder-der-funktionars-evolution" aria-label="Permalink to &quot;Cast-Profil: August Wöginger – Das Wunder der Funktionärs-Evolution&quot;">​</a></h1><p><strong>Status im Projekt:</strong> Hauptakteur (Klubobmann, ÖAAB-Bundesobmann, &quot;Harte Prosa&quot;-Experte)</p><h2 id="die-biografische-singularitat" tabindex="-1">Die Biografische Singularität <a class="header-anchor" href="#die-biografische-singularitat" aria-label="Permalink to &quot;Die Biografische Singularität&quot;">​</a></h2><p>August Wöginger ist das Paradebeispiel für eine Karriere in der &quot;politischen Sterilstation&quot;. Sein Lebenslauf weist eine Besonderheit auf, die ihn für unsere Mockumentary so wertvoll macht: <strong>Der völlige Mangel an Kontakt mit der freien Marktwirtschaft.</strong></p><h3 id="die-stationen-der-nicht-arbeit" tabindex="-1">Die Stationen der &quot;Nicht-Arbeit&quot;: <a class="header-anchor" href="#die-stationen-der-nicht-arbeit" aria-label="Permalink to &quot;Die Stationen der &quot;Nicht-Arbeit&quot;:&quot;">​</a></h3><ol><li><strong>HAK-Abschluss (1994):</strong> Direkt nach der Matura und dem Zivildienst (1995) erfolgte der Einstieg beim Roten Kreuz im Bezirkssekretariat Schärding.</li><li><strong>Der 22-jährige &quot;Angestellte&quot; (1995–2017):</strong> Wöginger blieb formell 22 Jahre beim Roten Kreuz. Bemerkenswert: Ab 2002 saß er bereits im Nationalrat. 15 Jahre lang war er also gleichzeitig Bundespolitiker und &quot;Angestellter&quot; in einem oberösterreichischen Sekretariat – ein Paradebeispiel für einen geschützten Arbeitsplatz im politischen Biotop.</li><li><strong>Betriebsrat ohne Betrieb (2006–2017):</strong> Er vertrat als Betriebsratsvorsitzender die Arbeitnehmer, während er in Wien bereits die Gesetze für sie machte. Eine klassische Doppelrolle der Macht.</li><li><strong>Die lückenlose Funktionärs-Kette:</strong> Vom Gemeinderat (2003) über den Bezirksobmann bis zum Klubobmann (2017). Er sammelt Ämter wie andere Panini-Sticker.</li></ol><h2 id="forensische-analyse-fur-die-mockumentary" tabindex="-1">Forensische Analyse für die Mockumentary: <a class="header-anchor" href="#forensische-analyse-fur-die-mockumentary" aria-label="Permalink to &quot;Forensische Analyse für die Mockumentary:&quot;">​</a></h2><p>In der Welt von August Wöginger existieren keine Kunden, keine Kündigungsfristen und kein wirtschaftliches Risiko. Er ist ein Produkt reiner Gremien-Logik. Seine &quot;Arbeit&quot; besteht aus Sitzungen, Bierzelt-Auftritten und dem Verfassen von Presseaussendungen (die im Projekt als &quot;Harte Prosa&quot; bekannt sind).</p><blockquote><p><em>&quot;Er war bereits Arbeitnehmervertreter, bevor er richtig wusste, was ein Betrieb ist.&quot;</em> – Archiv-Notiz 24.03.2026</p></blockquote>',9)])])}const m=r(a,[["render",o]]);export{c as __pageData,m as default};
